import re

files = ['index.html', 'learn.html', 'donate.html', 'tag-ai.html', 'tag-web-scraping.html']
issues = []

for f in files:
    with open(f) as fh:
        content = fh.read()
    # Check for mobile menu JS
    if 'mobile-nav' not in content:
        issues.append(f'{f}: missing mobile-nav')
    if 'menu-toggle' not in content:
        issues.append(f'{f}: missing menu-toggle')
    # Check cross-links
    for target in ['index.html', 'learn.html', 'donate.html', 'tag-ai.html', 'tag-web-scraping.html']:
        if target != f and target not in content:
            issues.append(f'{f}: missing link to {target}')
    # Check for OKLCH usage
    if 'oklch(' not in content:
        issues.append(f'{f}: no OKLCH colors')
    # Check responsive meta
    if 'viewport' not in content:
        issues.append(f'{f}: missing viewport meta')
    # Check Inter font
    if 'Inter' not in content:
        issues.append(f'{f}: missing Inter font')

# Specific interaction checks
with open('index.html') as fh:
    idx = fh.read()
if 'load-more-btn' not in idx:
    issues.append('index.html: missing load-more button')
if 'article-grid' not in idx:
    issues.append('index.html: missing article-grid')

with open('donate.html') as fh:
    don = fh.read()
if 'donation-tab' not in don:
    issues.append('donate.html: missing donation tabs')
if 'faq-item' not in don:
    issues.append('donate.html: missing FAQ items')

print('Issues found:', len(issues))
for i in issues:
    print(' -', i)
if not issues:
    print('All checks passed!')
"
